const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function retry(task, { attempts = 3, baseMs = 100 } = {}) {
  for (let i = 0; i < attempts; i++) {
    try {
      return await task();
    } catch (error) {
      if (i === attempts - 1) throw error;   // out of attempts
      await sleep(baseMs * 2 ** i);          // 100, 200, 400, ...
    }
  }
}
